class InvalidBtsType(Exception):
    """ Raised when BTS type is unsupported """
    pass


class InvalidAlarm(Exception):
    """ Raised when alarm has invalid data """
    pass


class BtsConnectionError(Exception):
    """ Raised when connection to BTS cannot be established """
    pass


class DisallowedAlarmsDetected(Exception):
    """ Raised when at least one disallowed alarm has been detected """
    pass


class WatchdogNotStarted(Exception):
    """ Raised when performing given action was not preceded with starting alarms watch """
    pass


class WatchdogAlreadyStarted(Exception):
    """ Raised when re-starting alarms watch was not preceded with stopping alarms watch """
    pass


class InvalidCallback(Exception):
    """ Raised when callback is not callable """
    pass


class AlarmInactive(Exception):
    """ Raised when alarm was not active during alarm checking """
    pass


class AlarmActive(Exception):
    """ Raised when alarm was active during alarm checking """
    pass
